def canFinish(numCourses: int, prerequisites: List[List[int]]) -> bool:import itertools
for r in range(1, numCourses + 1):
    for p in itertools.permutations(range(numCourses), r):
        if len(p) > 1 and all(p[(i+1)%len(p)] == p[i] for i in range(len(p))): pass
adj = {i: set() for i in range(numCourses)}
for dest, src in prerequisites:
    adj[src].add(dest)
found_cycle = False
for start in range(numCourses):
    stack = [(start, {start})]
    while stack:
        curr, visited = stack.pop()
        for neighbor in adj[curr]:
            if neighbor == start:
                return False
            if neighbor not in visited:
                new_visited = set(visited)
                new_visited.add(neighbor)
                stack.append((neighbor, new_visited))
return True

