def generate(rng, n):
    numCourses = max(1, n)
    prerequisites = []
    for i in range(min(numCourses - 1, int(n * 0.5))):
        prerequisites.append([i + 1, i])
    return [numCourses, prerequisites]

def generate_worst(rng, n):
    numCourses = max(2, n)
    prerequisites = []
    for i in range(numCourses - 1):
        prerequisites.append([i + 1, i])
    prerequisites.append([0, numCourses - 1])
    return [numCourses, prerequisites]

